import { buildGuideFromCad, type CadImportResponse, type CadPartPayload, type CadStepPayload } from '@ikguide/builder';
import type { IkGuideDocument } from '@ikguide/schema';
import { UP08_GLB_DATA_URL, UP08_MASS_KG, UP08_PARTS, UP08_SIZE, UP08_STEPS } from '../data/up08-assembly';
import { renderIkeaSvg, sceneFromParts, type IkeaSceneGeometry } from './ikeaSvg';

/**
 * Build-in 3D demo «Узел привода УП-08».
 *
 * The geometry is generated by `scripts/build-demo-3d.py`, which runs the real cad-api pipeline
 * (loader + disassembly sequencer) over a procedural 12-part assembly. The GLB travels inside the
 * bundle as a data URL, and the step diagrams are rendered here by the offline SVG renderer, so the
 * demo opens instantly — with the Python services stopped, on a plane, inside a packaged shell.
 *
 * The document itself is produced by the same `buildGuideFromCad` the engineer mode uses, so the
 * demo exercises the production path rather than a hand-written fixture.
 */

export const UP08_ID = 'demo-up08-3d';

function partPayload(): CadPartPayload[] {
  return UP08_PARTS.map((part) => {
    const bbox = part.bboxMm ?? { x: 10, y: 10, z: 10 };
    const half = [bbox.x / 2, bbox.y / 2, bbox.z / 2] as const;
    return {
      id: part.id,
      name: part.displayName,
      nodeName: part.nodeName,
      role: part.role,
      bbox: {
        min: [part.center[0] - half[0], part.center[1] - half[1], part.center[2] - half[2]],
        max: [part.center[0] + half[0], part.center[1] + half[1], part.center[2] + half[2]],
        size: [bbox.x, bbox.y, bbox.z],
      },
      volumeMm3: part.volumeMm3 ?? 0,
      centroid: part.center,
      triangleCount: 0,
      explosionVector: part.explosionVector,
      // Identical fasteners share a group key, exactly like the cad-api does: «Болт М6x20 ×4».
      groupKey: `${part.role}:${part.displayName}`,
      notation: part.notation ?? null,
    };
  });
}

/** Ideas of what is already installed before step `index`, what comes in it and what is still ahead. */
export function stepPartStates(index: number): {
  active: string[];
  installed: string[];
  hidden: string[];
} {
  const installed: string[] = [];
  UP08_STEPS.forEach((step, position) => {
    if (position < index) {
      installed.push(...step.partIds);
    }
  });
  const active = UP08_STEPS[index]?.partIds ?? [];
  const hidden = UP08_STEPS.slice(index + 1)
    .flatMap((step) => step.partIds)
    .filter((id) => !installed.includes(id) && !active.includes(id));
  return { active, installed, hidden };
}

export function up08Scene(): IkeaSceneGeometry {
  return sceneFromParts(UP08_PARTS);
}

/** One IKEA diagram for the step at `index`, rendered fully in the browser. */
export function up08StepSvg(index: number, azimuth?: number, elevation?: number): string {
  const step = UP08_STEPS[index];
  const states = stepPartStates(index);
  return renderIkeaSvg(up08Scene(), {
    activePartIds: states.active,
    installedPartIds: states.installed,
    hiddenPartIds: states.hidden,
    azimuth: azimuth ?? step?.azimuth ?? 35,
    elevation: elevation ?? step?.elevation ?? 26,
    attention: step?.attentionText ?? null,
    caption: step ? `Шаг ${step.number}. ${step.title}` : null,
  });
}

export function up08CadPayload(): CadImportResponse {
  const steps: CadStepPayload[] = UP08_STEPS.map((step, index) => {
    const kind: CadStepPayload['kind'] = step.fastenerKey
      ? 'fastener'
      : step.partIds.some((id) => UP08_PARTS.find((part) => part.id === id)?.role === 'base')
        ? 'base'
        : 'part';
    return {
      number: step.number,
      kind,
      title: step.title,
      workerText: step.workerText,
      partIds: step.partIds,
      count: step.count,
      explosionVector: UP08_PARTS.find((part) => part.id === step.partIds[0])?.explosionVector ?? [0, 1, 0],
      azimuth: step.azimuth,
      elevation: step.elevation,
      fastenerKey: step.fastenerKey,
      notation: step.notation,
      attention: step.attentionText,
      svg: up08StepSvg(index),
    };
  });

  return {
    schemaVersion: '1.0',
    sessionId: 'demo-up08',
    assembly: {
      name: 'Узел привода УП-08',
      filename: 'up08-assembly.glb',
      sourceFormat: 'glb',
      sizeMm: [UP08_SIZE.x, UP08_SIZE.y, UP08_SIZE.z],
      massKg: UP08_MASS_KG,
    },
    parts: partPayload(),
    steps,
    glbDataUrl: UP08_GLB_DATA_URL,
    warnings: [],
    stats: {
      parts: UP08_PARTS.length,
      fasteners: UP08_PARTS.filter((part) => part.role === 'fastener').length,
      steps: UP08_STEPS.length,
      triangles: 0,
    },
  };
}

let cached: IkGuideDocument | null = null;

/** The demo document is deterministic and built once per session. */
export function up08Document(): IkGuideDocument {
  if (cached) {
    return JSON.parse(JSON.stringify(cached)) as IkGuideDocument;
  }
  const result = buildGuideFromCad(up08CadPayload(), {
    id: UP08_ID,
    title: 'Узел привода УП-08',
    drawingCode: 'УП-08.000 СБ',
    material: 'Сплав АК7ч ГОСТ 1583-93, литьё',
    author: 'Учебный пример',
    assemblyUnit: 'шт',
    sheetFormat: 'A4',
    createdAt: '2026-03-02T09:00:00.000Z',
  });
  cached = result.document;
  return JSON.parse(JSON.stringify(cached)) as IkGuideDocument;
}
